(function(){var loadHandler=window['sl_{73A53C97-72DA-45CF-9CFF-054D6C4F2812}'];loadHandler&&loadHandler(19, '<div id="spr0_1049c0aa"><div id="spr1_1049c0aa" class="kern slide"><img id="img2_1049c0aa" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/><div id="spr3_1049c0aa" style="left:986.15px;top:648.5px;"><div id="spr4_1049c0aa"><img id="img0_1049c0aa" src="data:image/png;base64," width="273.75" height="62.25" alt="" style="left:0.06px;top:-0.094px;"/></div></div></div><div id="spr2_1049c0aa" class="kern slide"><div id="svg64_1049c0aa" style="left:1117.801px;top:635.151px;"><svg width="154" height="38" viewBox="0 0 154 38"><path fill="#fee599" d="M0,0 h153.6 v37.44 h-153.6 Z"/></svg></div><div id="spr5_1049c0aa" style="left:1117.801px;top:635.151px;"><div style="width:0px;"><span id="txt0_1049c0aa" class="nokern relpos" data-width="66.201172" style="left:9.598px;top:4.764px;">Book A  </span> <span id="txt1_1049c0aa" class="nokern relpos" data-width="62.023438" style="left:9.592px;top:1.931px;">Page 4</span></div></div><div id="spr6_1049c0aa" style="left:1275.879px;top:520.722px;"><div style="width:0px;"><span id="txt2_1049c0aa" class="nokern" data-width="694.289062" style="left:31.441px;top:-2.623px;">Can you explain how reflexes</span></div><div style="width:0px;"><span id="txt3_1049c0aa" class="nokern" data-width="531.065125" style="left:113.02px;top:67.777px;">can be advantageous?</span></div></div><div id="svg65_1049c0aa" style="left:1292.445px;top:413.804px;"><svg width="848" height="129" viewBox="0 0 848 129"><path fill="#e2f0d9" d="M0,0 h847.059 v128.2 h-847.059 Z"/></svg></div><div id="spr7_1049c0aa" style="left:1292.445px;top:413.804px;"><div style="width:0px;"><span id="txt4_1049c0aa" class="nokern relpos" data-width="133.542969" style="left:9.6px;top:6.35px;">Reflexes are </span> <span id="txt5_1049c0aa" class="nokern relpos" data-width="152.413406" style="left:9.593px;top:6.35px;">advantageous</span> <span id="txt6_1049c0aa" class="nokern relpos" data-width="534.282532" style="left:9.587px;top:6.35px;"> because they allow the body to respond to danger or</span></div><div style="width:0px;"><span id="txt7_1049c0aa" class="nokern" data-width="796.244141" style="left:9.6px;top:36.27px;">harm almost instantly, without needing the brain to process the information first.</span></div><div style="width:0px;"><span id="txt8_1049c0aa" class="nokern" data-width="801.246704" style="left:9.6px;top:66.19px;">This quick, automatic reaction helps protect the body from injury — for example,</span></div><div style="width:0px;"><span id="txt9_1049c0aa" class="nokern" data-width="705.632812" style="left:9.6px;top:96.11px;">pulling your hand away from a hot stove before you even feel the pain.</span></div></div><div id="spr8_1049c0aa" style="left:1224.769px;"><div id="svg66_1049c0aa" style="left:5.031px;top:4.251px;"><svg width="47" height="28" viewBox="0 0 47 28"><path fill="#c00000" d="M0,0 h46.08 v27.429 h-46.08 Z"/></svg></div><div id="svg67_1049c0aa" style="left:0px;top:0px;"><svg width="65" height="28" viewBox="0 0 65 28"><path fill="none" d="M0,0 h64.174 v27.433 h-64.174 Z"/></svg></div><div id="spr9_1049c0aa"><div style="width:0px;"><span id="txt10_1049c0aa" class="nokern" data-width="42.155083" style="left:9.598px;top:2.268px;">END</span></div></div></div><div id="spr10_1049c0aa" style="left:471.011px;top:31.68px;"><div id="spr11_1049c0aa"><img id="img1_1049c0aa" src="data:image/png;base64," width="765.75" height="510" alt="" style="left:-0.099px;top:0.122px;"/></div></div><div id="svg68_1049c0aa" style="left:56.758px;top:60.708px;"><svg width="563" height="46" viewBox="0 0 563 46"><path fill="#ffffff" d="M0,0 h562.95 v45.143 h-562.95 Z"/></svg></div><div id="spr12_1049c0aa" style="left:56.758px;top:60.708px;"><div style="width:0px;"><span id="txt11_1049c0aa" class="nokern relpos" data-width="140.054688" style="left:9.6px;top:7.724px;">The reflex </span> <span id="txt12_1049c0aa" class="nokern relpos" data-width="351.736328" style="left:9.593px;top:7.724px;">contains five essential parts:</span></div></div><div id="svg69_1049c0aa" style="left:56.758px;top:124.262px;"><svg width="232" height="42" viewBox="0 0 232 42"><path fill="#ffffff" d="M0,0 h231.415 v41.764 h-231.415 Z"/></svg></div><div id="spr13_1049c0aa" style="left:56.758px;top:124.262px;"><div style="width:0px;"><span id="txt13_1049c0aa" class="nokern relpos" data-width="28.166016" style="left:9.6px;top:7.442px;">1. </span> <span id="txt14_1049c0aa" class="nokern relpos" data-width="109.806641" style="left:9.593px;top:7.442px;">Receptor</span></div></div><div id="svg70_1049c0aa" style="left:61.31px;top:179.507px;"><svg width="271" height="42" viewBox="0 0 271 42"><path fill="#ffffff" d="M0,0 h270.398 v41.764 h-270.398 Z"/></svg></div><div id="spr14_1049c0aa" style="left:61.31px;top:179.507px;"><div style="width:0px;"><span id="txt15_1049c0aa" class="nokern relpos" data-width="28.166016" style="left:9.6px;top:7.442px;">2. </span> <span id="txt16_1049c0aa" class="nokern relpos" data-width="192.857422" style="left:9.593px;top:7.442px;">Sensory neuron</span></div></div><div id="svg71_1049c0aa" style="left:62.34px;top:234.752px;"><svg width="416" height="42" viewBox="0 0 416 42"><path fill="#ffffff" d="M0,0 h415.601 v41.764 h-415.601 Z"/></svg></div><div id="spr15_1049c0aa" style="left:62.34px;top:234.752px;"><div style="width:0px;"><span id="txt17_1049c0aa" class="nokern relpos" data-width="28.166016" style="left:9.6px;top:7.442px;">3. </span> <span id="txt18_1049c0aa" class="nokern relpos" data-width="313.871094" style="left:9.593px;top:7.442px;">Interneuron of spinal cord</span></div></div><div id="svg72_1049c0aa" style="left:61.31px;top:289.997px;"><svg width="416" height="42" viewBox="0 0 416 42"><path fill="#ffffff" d="M0,0 h415.601 v41.764 h-415.601 Z"/></svg></div><div id="spr16_1049c0aa" style="left:61.31px;top:289.997px;"><div style="width:0px;"><span id="txt19_1049c0aa" class="nokern relpos" data-width="28.166016" style="left:9.6px;top:7.442px;">4. </span> <span id="txt20_1049c0aa" class="nokern relpos" data-width="163.231781" style="left:9.593px;top:7.442px;">Motor neuron</span></div></div><div id="svg73_1049c0aa" style="left:62.34px;top:345.242px;"><svg width="416" height="42" viewBox="0 0 416 42"><path fill="#ffffff" d="M0,0 h415.601 v41.764 h-415.601 Z"/></svg></div><div id="spr17_1049c0aa" style="left:62.34px;top:345.242px;"><div style="width:0px;"><span id="txt21_1049c0aa" class="nokern relpos" data-width="28.166016" style="left:9.6px;top:7.442px;">5. </span> <span id="txt22_1049c0aa" class="nokern relpos" data-width="95.717453" style="left:9.593px;top:7.442px;">Effector</span></div></div><div id="svg74_1049c0aa" style="left:88.387px;top:405.416px;"><svg width="416" height="112" viewBox="0 0 416 112"><path fill="#ffffff" d="M0,0 h415.601 v111.747 h-415.601 Z"/></svg></div><div id="spr18_1049c0aa" style="left:88.387px;top:405.416px;"><div style="width:0px;"><span id="txt23_1049c0aa" class="nokern" data-width="359.045593" style="left:9.6px;top:7.442px;">By the time your brain interprets</span></div><div style="width:0px;"><span id="txt24_1049c0aa" class="nokern" data-width="356.274750" style="left:9.6px;top:42.095px;">the information, the effector has</span></div><div style="width:0px;"><span id="txt25_1049c0aa" class="nokern" data-width="216.891937" style="left:9.6px;top:76.749px;">already responded,</span></div></div><div id="svg76_1049c0aa" style="left:65.5px;top:407.772px;"><svg width="29" height="40" viewBox="-4 -4 29 40"><g fill="none"><path fill="#c00000" stroke="#ff0000" stroke-width="2.667" stroke-linecap="butt" stroke-linejoin="miter" transform="translate(1.333333,1.333333)" d="M0,21.563 v-14.376 L8.777,7.188 v-7.188 l8.777,14.376 l-8.777,14.376 v-7.188 Z"/></g></svg></div><div id="svg77_1049c0aa" style="left:1028.525px;top:87.081px;"><svg width="182" height="77" viewBox="0 0 182 77"><path fill="#e7e6e6" d="M0,0 h181.668 v76.756 h-181.668 Z"/></svg></div><div id="spr19_1049c0aa" style="left:1028.525px;top:87.081px;"><div style="width:0px;"><span id="txt26_1049c0aa" class="nokern" data-width="137.947922" style="left:21.834px;top:7.442px;">Signal Sent</span></div><div style="width:0px;"><span id="txt27_1049c0aa" class="nokern" data-width="140.743500" style="left:20.334px;top:42.095px;">to the Brain</span></div></div><div id="svg7_1049c0aa" style="left:212.266px;top:106.329px;"><svg width="498" height="46" viewBox="-2.885 -0.687 498 46"><g fill="none"><g transform="translate(0.115458,3.764547)"><g fill="#c00000" stroke="none" transform="translate(-0.115444,-3.764545)"><path stroke="#c00000" stroke-width="3" stroke-linecap="butt" transform="translate(0.115444,3.764545)" d="M0,38.148 L486.117,0.619"/><path transform="matrix(0.997033,-0.076973,0.076973,0.997033,0.115459,41.912312)" d="M495.601,0 L486.671,4.465 V-4.465 Z"/></g></g></g></svg></div><div id="spr20_1049c0aa" style="left:677.128px;top:34.261px;"><div style="width:0px;"><span id="txt28_1049c0aa" class="nokern relpos" data-width="122.209633" style="left:9.6px;top:7.165px;">Receptor in </span> <span id="txt29_1049c0aa" class="nokern relpos" data-width="45.355469" style="left:9.593px;top:7.165px;">skin</span></div></div><div id="spr21_1049c0aa" style="left:800.383px;top:82.213px;"><div style="width:0px;"><span id="txt30_1049c0aa" class="nokern" data-width="134.815750" style="left:9.6px;top:7.165px;">Pain receptor</span></div></div><div id="svg15_1049c0aa" style="left:758.345px;top:101.326px;"><svg width="50" height="12" viewBox="-0.402 -0.672 50 12"><g fill="none"><g transform="translate(0.081055,0.661723)"><g fill="#595959" stroke="none" transform="translate(-0.08107,-0.66172)"><path stroke="#595959" stroke-width="1.333" stroke-linecap="butt" transform="translate(0.08107,0.66172)" d="M48,0 L7.091,5.012"/><path transform="matrix(-0.992578,0.121608,-0.121608,-0.992578,48.08107,0.661719)" d="M48.359,0 L40.421,3.969 V-3.969 Z"/></g></g></g></svg></div><div id="svg23_1049c0aa" style="left:293.853px;top:182.595px;"><svg width="532" height="26" viewBox="-2.949 -0.306 532 26"><g fill="none"><g transform="translate(0.051412,4.156494)"><g fill="#c00000" stroke="none" transform="translate(-0.051409,-4.1565)"><path stroke="#c00000" stroke-width="3" stroke-linecap="butt" transform="translate(0.051409,4.1565)" d="M0,18.115 L520.218,0.275"/><path transform="matrix(0.999413,-0.034272,0.034272,0.999413,0.051409,22.271521)" d="M528.561,0 L519.631,4.465 V-4.465 Z"/></g></g></g></svg></div><div id="spr22_1049c0aa" style="left:825.104px;top:137.588px;"><div style="width:0px;"><span id="txt31_1049c0aa" class="nokern" data-width="160.027985" style="left:9.6px;top:7.165px;">Sensory neuron</span></div></div><div id="svg31_1049c0aa" style="left:424.497px;top:245.041px;"><svg width="554" height="20" viewBox="-2.966 -0.2 554 20"><g fill="none"><g transform="translate(0.033569,4.264079)"><g fill="#c00000" stroke="none" transform="translate(-0.03354,-4.26407)"><path stroke="#c00000" stroke-width="3" stroke-linecap="butt" transform="translate(0.03354,4.26407)" d="M0,12.313 L541.992,0.18"/><path transform="matrix(0.99975,-0.02238,0.02238,0.99975,0.03357,16.576958)" d="M550.165,0 L541.235,4.465 V-4.465 Z"/></g></g></g></svg></div><div id="spr23_1049c0aa" style="left:875.984px;top:259.606px;"><div style="width:0px;"><span id="txt32_1049c0aa" class="nokern" data-width="115.934242" style="left:9.6px;top:7.165px;">Interneuron</span></div></div><div id="svg39_1049c0aa" style="left:1003.451px;top:232.637px;"><svg width="87" height="46" viewBox="-1.043 -2.972 87 46"><g fill="none"><g transform="translate(0.290446,0.600077)"><g fill="#595959" stroke="none" transform="translate(-0.290448,-0.600067)"><path stroke="#595959" stroke-width="1.333" stroke-linecap="butt" transform="translate(0.290448,0.600067)" d="M0,40.307 L76.843,3.113"/><path transform="matrix(0.900103,-0.435677,0.435677,0.900103,0.290451,40.906734)" d="M92.515,0 L84.577,3.969 V-3.969 Z"/></g></g></g></svg></div><div id="spr24_1049c0aa" style="left:1088.632px;top:345.242px;"><div style="width:0px;"><span id="txt33_1049c0aa" class="nokern" data-width="113.399734" style="left:9.6px;top:7.165px;">Spinal cord</span></div></div><div id="svg47_1049c0aa" style="left:1161.7px;top:319.895px;"><svg width="18" height="35" viewBox="-3.022 -1.257 18 35"><g fill="none"><g transform="translate(0.648519,0.253764)"><g fill="#595959" stroke="none" transform="translate(-0.648546,-0.253771)"><path stroke="#595959" stroke-width="1.333" stroke-linecap="butt" transform="translate(0.648546,0.253771)" d="M12.879,31.285 L2.719,6.606"/><path transform="matrix(-0.380657,-0.924716,0.924716,-0.380657,13.527079,31.539125)" d="M33.832,0 L25.894,3.969 V-3.969 Z"/></g></g></g></svg></div><div id="svg55_1049c0aa" style="left:272.076px;top:310.862px;"><svg width="630" height="36" viewBox="-2.932 -1.502 630 36"><g fill="none"><g transform="translate(0.067749,1.498474)"><g fill="#c00000" stroke="none" transform="translate(-0.067742,-1.498469)"><path stroke="#c00000" stroke-width="3" stroke-linecap="butt" transform="translate(0.067742,1.498469)" d="M0,0 L617.905,27.934"/><path transform="matrix(0.99898,0.045161,-0.045161,0.99898,0.067742,1.49847)" d="M626.573,0 L617.643,4.465 V-4.465 Z"/></g></g></g></svg></div><div id="spr25_1049c0aa" style="left:918.24px;top:336.27px;"><div style="width:0px;"><span id="txt34_1049c0aa" class="nokern" data-width="57.939453" style="left:9.6px;top:7.165px;">Motor</span></div><div style="width:0px;"><span id="txt35_1049c0aa" class="nokern" data-width="70.578773" style="left:9.6px;top:38.171px;">neuron</span></div></div><div id="svg63_1049c0aa" style="left:203.77px;top:366.108px;"><svg width="550" height="19" viewBox="-2.969 -1.5 550 19"><g fill="none"><g transform="translate(0.031453,1.499674)"><g fill="#c00000" stroke="none" transform="translate(-0.031457,-1.49967)"><path stroke="#c00000" stroke-width="3" stroke-linecap="butt" transform="translate(0.031457,1.49967)" d="M0,0 L538.653,11.299"/><path transform="matrix(0.99978,0.020971,-0.020971,0.99978,0.031457,1.49967)" d="M546.808,0 L537.878,4.465 V-4.465 Z"/></g></g></g></svg></div><div id="spr26_1049c0aa" style="left:743.535px;top:317.074px;"><div style="width:0px;"><span id="txt36_1049c0aa" class="nokern" data-width="78.104813" style="left:9.6px;top:7.165px;">Effector</span></div></div><div id="spr27_1049c0aa" style="left:460.667px;top:158.656px;"><div style="width:0px;"><span id="txt37_1049c0aa" class="nokern" data-width="95.713539" style="left:9.6px;top:7.165px;">Stimulus</span></div></div><div id="spr28_1049c0aa" style="left:507.303px;top:375.413px;"><div style="width:0px;"><span id="txt38_1049c0aa" class="nokern" data-width="108.330727" style="left:9.6px;top:7.165px;">Response</span></div></div><div id="spr29_1049c0aa" style="left:88.387px;top:539.3px;"><div style="width:0px;"><span id="txt39_1049c0aa" class="nokern relpos" data-width="141.398438" style="left:9.6px;top:6.441px;">Reflexes are </span> <span id="txt40_1049c0aa" class="nokern relpos" data-width="161.378906" style="left:9.593px;top:6.441px;">advantageous</span> <span id="txt41_1049c0aa" class="nokern relpos" data-width="704.414062" style="left:9.587px;top:6.441px;"> because they allow the body to respond to danger or harm almost</span></div><div style="width:0px;"><span id="txt42_1049c0aa" class="nokern" data-width="704.378906" style="left:9.6px;top:38.121px;">instantly, without needing the brain to process the information first.</span></div></div><div id="spr30_1049c0aa" style="left:90.21px;top:615.529px;"><div style="width:0px;"><span id="txt43_1049c0aa" class="nokern" data-width="848.378906" style="left:9.6px;top:6.018px;">This quick, automatic reaction helps protect the body from injury — for example,</span></div><div style="width:0px;"><span id="txt44_1049c0aa" class="nokern" data-width="747.140625" style="left:9.6px;top:34.818px;">pulling your hand away from a hot stove before you even feel the pain.</span></div></div></div></div>', '{"s":[]}');})();